using System.Globalization;

namespace FateAndFridge.Api.Services;

/// <summary>
/// Archive file naming and storage locations for backups
/// (docs/M13_PLAN.md §1.6): manual archives live directly in
/// <c>{DataDir}/backups</c> and safety archives in
/// <c>{DataDir}/backups/safety</c>. Names are generated by the server from the
/// app version and the injected UTC clock, never from user input, so a filename
/// can never escape the backups directory.
/// </summary>
public static class BackupNaming
{
    /// <summary>The archive extension (docs/M13_PLAN.md §1.4).</summary>
    public const string Extension = ".ffbackup";

    /// <summary>Directory created under <c>{DataDir}/backups</c> for in-flight dumps.</summary>
    public const string TempDirectoryName = ".tmp";

    /// <summary>Directory under <c>{DataDir}/backups</c> for pre-restore safety archives.</summary>
    public const string SafetyDirectoryName = "safety";

    /// <summary>
    /// Name of one manual archive:
    /// <c>fatefridge-&lt;appversion&gt;-&lt;UTC yyyyMMddTHHmmssZ&gt;.ffbackup</c>
    /// (docs/M13_PLAN.md §1.6). The timestamp is always converted to UTC, so
    /// the name is stable across host timezones.
    /// </summary>
    public static string ForManualBackup(string appVersion, DateTimeOffset createdAt)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(appVersion);

        var timestamp = createdAt
            .ToUniversalTime()
            .ToString("yyyyMMdd'T'HHmmss'Z'", CultureInfo.InvariantCulture);

        return $"fatefridge-{appVersion}-{timestamp}{Extension}";
    }

    /// <summary>
    /// Disambiguates a same-second name collision (two app instances, or a
    /// clock that did not advance) while keeping the documented shape:
    /// <c>…-2.ffbackup</c>, <c>…-3.ffbackup</c>, and so on.
    /// </summary>
    public static string WithSuffix(string filename, int attempt)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(filename);
        ArgumentOutOfRangeException.ThrowIfLessThan(attempt, 2);

        var stem = filename.EndsWith(Extension, StringComparison.Ordinal)
            ? filename[..^Extension.Length]
            : filename;

        return $"{stem}-{attempt.ToString(CultureInfo.InvariantCulture)}{Extension}";
    }
}
